# WAR ARENA - Consent Ledger (legal audit trail) - Installer
# Records each user agreement to Terms/Privacy with timestamp + version.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-consent.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Consent Ledger installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/legal/consent.ts" ""
Write-B64 "tests/unit/consent.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Consent ledger installed. Expected: 948 passed + 1 skipped." -ForegroundColor Green
